// VideoCarousel.jsx (replace existing)
import React, { useRef, useState, useEffect } from "react";

/*
Works with direct .mp4 links (Coverr/CDN). Uses <source> and crossOrigin,
and shows a friendly message if video fails to load.
*/
export default function VideoCarousel({ videoList = [] }) {
  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [error, setError] = useState(false);
  const vRef = useRef(null);

  useEffect(() => {
    // ensure play/pause sync when index changes
    if (!vRef.current) return;
    vRef.current.pause();
    setPlaying(false);
    setError(false);
  }, [index]);

  function togglePlay() {
    if (!vRef.current) return;
    if (playing) {
      vRef.current.pause();
      setPlaying(false);
    } else {
      // try to play, catch promise rejection
      const p = vRef.current.play();
      if (p && p.then) {
        p.then(() => setPlaying(true)).catch(() => {
          setPlaying(false);
          setError(true);
        });
      } else {
        setPlaying(true);
      }
    }
  }

  function prev() {
    setIndex(i => (i - 1 + videoList.length) % videoList.length);
  }
  function next() {
    setIndex(i => (i + 1) % videoList.length);
  }

  if (!videoList || videoList.length === 0) {
    return <div className="card">No banner videos configured.</div>;
  }

  return (
    <section className="video-banner card">
      <div className="video-wrapper" style={{ position: "relative" }}>
        <video
          ref={vRef}
          className="banner-video"
          playsInline
          controls={false}
          preload="metadata"
          crossOrigin="anonymous"
          onError={() => setError(true)}
          onEnded={() => setPlaying(false)}
        >
          {/* use <source> so browser can detect type */}
          <source src={videoList[index]} type="video/mp4" />
          Your browser does not support HTML5 video.
        </video>

        {/* If video fails to load, show fallback image / message */}
        {error && (
          <div
            style={{
              position: "absolute",
              inset: 0,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              background: "rgba(0,0,0,0.5)",
              color: "#fff",
              zIndex: 5,
              padding: 20,
            }}
          >
            <div>
              <p style={{ marginBottom: 8 }}>Video failed to load.</p>
              <p style={{ fontSize: 13, opacity: 0.9 }}>
                Try opening the video URL directly in a new tab to check (or use local file).
              </p>
            </div>
          </div>
        )}

        <button className="vc-btn prev" onClick={prev} aria-label="Previous">‹</button>
        <button className="vc-btn next" onClick={next} aria-label="Next">›</button>

        {/* big play/pause overlay - ensure pointer-events allow clicks on it */}
        <button
          className="play-overlay"
          onClick={togglePlay}
          aria-label={playing ? "Pause" : "Play"}
          style={{ zIndex: 6 }}
        >
          {playing ? "❚❚" : "►"}
        </button>

        <div className="video-index" style={{ zIndex: 6 }}>
          {index + 1}/{videoList.length}
        </div>
      </div>
    </section>
  );
}
